import math
    import random
    import time

    LANGUAGE_WRAPPER = 'On an n×n toroidal chessboard (rows and columns wrap around), all entries start at 0. You may perform operations of two types, and each edge may be used at most once: (H) choose a horizontally adjacent pair and add a to both entries; (V) choose a vertically adjacent pair and add b to both entries. After some sequence of operations, suppose the sum of the entries along every row, every column, and along every wrap-around main and anti-diagonal are all equal to the same target value t_target. Among all such sequences, determine the minimum number of operations required; if no such sequence exists, output 0. Compute this minimum for n = {n}, with a = {a}, b = {b}, and target = {t_target}.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# Pick grid size
n = rng.randint(5, 80)
# Pick operation increments a, b
a, b = rng.sample(list(range(2, 10)), 2)
# Decide X,Y to ensure feasibility and non-triviality
if n % 2 == 1:
    # odd n: only 0 or 2-regular spanning subgraphs exist as perfect matchings do not exist
    choices = [(2,0), (0,2), (2,2)]
    X, Y = rng.choice(choices)
else:
    # even n: allow 0,1,2; avoid trivial X+Y=1 to keep it non-trivial
    candidates = []
    for X in [0,1,2]:
        for Y in [0,1,2]:
            if X+Y >= 2:  # enforce harder instance
                candidates.append((X,Y))
    X, Y = rng.choice(candidates)
t_target = a * X + b * Y
# Safety: ensure t_target > 0 (non-zero operations required)
if t_target <= 0:
    # retry with safe default
    X, Y = (2, 0) if n % 2 == 1 else (1, 1)
    t_target = a * X + b * Y
return {'n': n, 'a': a, 'b': b, 't_target': t_target}

    def verifier(assign):
# Verify types and domain
try:
    n = int(assign['n'])
    a = int(assign['a'])
    b = int(assign['b'])
    t = int(assign['t_target'])
except Exception:
    # Invalid assignment
    return False, None  # invalid types
if n < 2 or a <= 0 or b <= 0:
    # Domain invalid
    return False, None
# Allowed regularities per orientation given parity
if n % 2 == 0:
    allowed = [0, 1, 2]
else:
    allowed = [0, 2]
# Enumerate feasible (X, Y): per-vertex horizontal degree X and vertical degree Y, with each edge used at most once
solutions = []
for X in allowed:
    for Y in allowed:
        if X == 0 and Y == 0:
            continue
        if a * X + b * Y == t:
            solutions.append((X, Y))
if not solutions:
    # No way to achieve the uniform per-cell target under constraints
    return True, 0
# Minimal operations: each X-regular horizontal spanning subgraph contributes X*n^2/2 edges, likewise vertical
# Total operations m = (X + Y) * n^2 / 2
best = None
for X, Y in solutions:
    m = (X + Y) * n * n // 2
    # Since X+Y and n^2 are integers and parity guarantees integrality, integer division is safe
    if best is None or m < best:
        best = m
return True, best


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

